import java.util.Scanner;

abstract class Employee {
    protected final String name;
    protected final int salary;

    Employee(String name, int salary) {
        this.name = name;
        this.salary = salary;
    }

    abstract String role();
}

interface Bonusable {
    int bonus();
}

class Manager extends Employee implements Bonusable {
    Manager(String name, int salary) {
        super(name, salary);
    }

    @Override
    String role() {
        return "管理職";
    }

    @Override
    public int bonus() {
        return salary / 10;
    }
}

class Staff extends Employee {
    Staff(String name, int salary) {
        super(name, salary);
    }

    @Override
    String role() {
        return "一般";
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        Employee[] employees = new Employee[k];

        for (int i = 0; i < k; i++) {
            String type = sc.next();
            String name = sc.next();
            int salary = sc.nextInt();
            if (type.equals("M")) {
                employees[i] = new Manager(name, salary);
            } else {
                employees[i] = new Staff(name, salary);
            }
        }

        int sum = 0;
        for (Employee e : employees) {
            int total = e.salary;
            if (e instanceof Bonusable b) {
                total += b.bonus();
            }
            System.out.println(e.name + " " + e.role() + " 支給 " + total);
            sum += total;
        }
        System.out.println("合計 " + sum);
    }
}
